      { en: "the benefit of / a drawback of / the impact on / a solution to …", ar: "فائدة … / عيب … / تأثير في … / حل لـ …", use: "الاسم + حرف الجر الصحيح" },
      { en: "On balance, I think … / All things considered, …", ar: "بعد الموازنة أرى أن … / بعد النظر في كل الأمور …", use: "الخلاصة بعد موازنة الآراء" }
